#[doc(alias = "gimp_rectangle_intersect")]
pub fn rectangle_intersect(
    x1: i32,
    y1: i32,
    width1: i32,
    height1: i32,
    x2: i32,
    y2: i32,
    width2: i32,
    height2: i32,
) -> Option<(i32, i32, i32, i32)> {
    unsafe {
        let mut dest_x = std::mem::MaybeUninit::uninit();
        let mut dest_y = std::mem::MaybeUninit::uninit();
        let mut dest_width = std::mem::MaybeUninit::uninit();
        let mut dest_height = std::mem::MaybeUninit::uninit();
        let ret = from_glib(ffi::gimp_rectangle_intersect(
            x1,
            y1,
            width1,
            height1,
            x2,
            y2,
            width2,
            height2,
            dest_x.as_mut_ptr(),
            dest_y.as_mut_ptr(),
            dest_width.as_mut_ptr(),
            dest_height.as_mut_ptr(),
        ));
        if ret {
            Some((
                dest_x.assume_init(),
                dest_y.assume_init(),
                dest_width.assume_init(),
                dest_height.assume_init(),
            ))
        } else {
            None
        }
    }
}

#[doc(alias = "gimp_rectangle_union")]
