pub fn text_get_extents_font(text: &str, size: f64, font: &Font) -> Option<(i32, i32, i32, i32)> {
    unsafe {
        let mut width = std::mem::MaybeUninit::uninit();
        let mut height = std::mem::MaybeUninit::uninit();
        let mut ascent = std::mem::MaybeUninit::uninit();
        let mut descent = std::mem::MaybeUninit::uninit();
        let ret = from_glib(ffi::gimp_text_get_extents_font(
            text.to_glib_none().0,
            size,
            font.to_glib_none().0,
            width.as_mut_ptr(),
            height.as_mut_ptr(),
            ascent.as_mut_ptr(),
            descent.as_mut_ptr(),
        ));
        if ret {
            Some((
                width.assume_init(),
                height.assume_init(),
                ascent.assume_init(),
                descent.assume_init(),
            ))
        } else {
            None
        }
    }
}

